import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { exit, snap, spring } from "../lib/motion";
import { cn } from "../lib/utils";
import { Button } from "./button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger
} from "./dropdown-menu";
import { type IconName } from "./icon";

import styles from "./floating-action-bar.module.css";

export interface FloatingAction {
  label: string;
  icon?: IconName;
  onClick: () => void;
  danger?: boolean;
  disabled?: boolean;
  loading?: boolean;
}

export type FloatingActionBarProps = {
  count: number;
  total?: number;
  onSelectAll?: () => void;
  actions?: readonly FloatingAction[];
  moreActions?: readonly FloatingAction[];
  onClear: () => void;
  noun?: string;
  placement?: "fixed" | "contained";
  label?: string;
  className?: string;
};

const roving = (event: React.KeyboardEvent<HTMLDivElement>, onClear: () => void) => {
  if (!event.currentTarget.contains(event.target as Node) || event.defaultPrevented) return;
  if (event.key === "Escape") {
    event.preventDefault();
    event.stopPropagation();
    onClear();
    return;
  }
  if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
  const buttons = [...event.currentTarget.querySelectorAll<HTMLElement>("button:not(:disabled)")];
  const index = buttons.indexOf(document.activeElement as HTMLElement);
  if (index === -1) return;
  event.preventDefault();
  const next =
    event.key === "Home"
      ? 0
      : event.key === "End"
        ? buttons.length - 1
        : (index + (event.key === "ArrowRight" ? 1 : -1) + buttons.length) % buttons.length;
  buttons[next]?.focus();
};

export const FloatingActionBar = ({
  count,
  total,
  onSelectAll,
  actions = [],
  moreActions = [],
  onClear,
  noun = "selected",
  placement = "fixed",
  label = "Bulk actions",
  className
}: FloatingActionBarProps) => {
  const reduced = useReducedMotion();
  const lastCount = React.useRef(count);
  const returnFocus = React.useRef<HTMLElement | null>(null);
  const bar = React.useRef<HTMLDivElement | null>(null);
  if (count > 0) lastCount.current = count;
  const shown = count > 0;
  React.useEffect(() => {
    if (shown || !bar.current?.contains(document.activeElement)) return;
    returnFocus.current?.focus();
  }, [shown]);
  const visibleCount = shown ? count : lastCount.current;
  const actionsRef = React.useRef<HTMLSpanElement | null>(null);
  const widths = React.useRef(new Map<string, number>());
  const [fit, setFit] = React.useState(actions.length);
  const measure = React.useCallback(() => {
    const node = bar.current;
    const group = actionsRef.current;
    if (!node || !group) return;
    group.querySelectorAll<HTMLElement>("[data-action-label]").forEach((button) => {
      widths.current.set(button.dataset.actionLabel ?? "", button.offsetWidth);
    });
    const more = group.querySelector<HTMLElement>("[data-action-more]");
    if (more) widths.current.set("�more", more.offsetWidth);
    const container =
      node.dataset.placement === "contained"
        ? ((node.offsetParent as HTMLElement | null)?.clientWidth ?? window.innerWidth)
        : window.innerWidth;
    const gap = parseFloat(getComputedStyle(group).columnGap) || 0;
    const limit = Math.min(container - 32, parseFloat(getComputedStyle(node).maxWidth) || Infinity);
    const available = limit - (node.offsetWidth - group.offsetWidth);
    const known = actions.every((action) => widths.current.has(action.label));
    if (!known) return;
    const moreWidth = widths.current.get("�more") ?? 72;
    let next = actions.length;
    const total = (k: number) =>
      actions
        .slice(0, k)
        .reduce((sum, action) => sum + (widths.current.get(action.label) ?? 0), 0) +
      Math.max(0, k - 1 + (k < actions.length || moreActions.length ? 1 : 0)) * gap +
      (k < actions.length || moreActions.length ? moreWidth : 0);
    while (next > 0 && total(next) > available + 0.5) next -= 1;
    setFit((current) => (current === next ? current : next));
  }, [actions, moreActions.length]);
  const labels = actions.map((action) => action.label).join("�");
  React.useLayoutEffect(() => {
    setFit(labels ? labels.split("�").length : 0);
  }, [labels]);
  React.useLayoutEffect(() => {
    if (!shown) return undefined;
    measure();
    const observer = new ResizeObserver(measure);
    const node = bar.current;
    if (node?.offsetParent) observer.observe(node.offsetParent);
    window.addEventListener("resize", measure);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", measure);
    };
  });
  const inline = actions.slice(0, fit);
  const overflow = [...actions.slice(fit), ...moreActions];
  return (
    <AnimatePresence>
      {shown && (
        <motion.div
          ref={bar}
          key="bar"
          data-slot="floating-action-bar"
          data-placement={placement}
          role="toolbar"
          data-v4-escape-owner=""
          aria-label={label}
          className={cn(styles.bar, className)}
          initial={{ opacity: 0, y: reduced ? 0 : 16 }}
          animate={{ opacity: 1, y: 0, transition: reduced ? snap : spring.moderate }}
          exit={{ opacity: 0, y: reduced ? 0 : 16, transition: reduced ? snap : exit.moderate }}
          onFocus={(event: React.FocusEvent<HTMLDivElement>) => {
            const from = event.relatedTarget as HTMLElement | null;
            if (from && !event.currentTarget.contains(from)) returnFocus.current = from;
          }}
          onKeyDown={(event: React.KeyboardEvent<HTMLDivElement>) => roving(event, onClear)}
        >
          <span className={styles.count} role="status">
            <span className={styles.number}>{visibleCount}</span>
            <span className={styles.noun}>{noun}</span>
          </span>
          {total !== undefined && onSelectAll && visibleCount < total && (
            <Button variant="link" size="sm" className={styles.selectAll} onClick={onSelectAll}>
              Select all {total}
            </Button>
          )}
          <span className={styles.rule} aria-hidden="true" />
          <span className={styles.actions} ref={actionsRef}>
            {inline.map((action) => (
              <Button
                key={action.label}
                data-action-label={action.label}
                variant={action.danger ? "danger-ghost" : "ghost"}
                size="sm"
                icon={action.icon}
                disabled={action.disabled}
                loading={action.loading}
                onClick={action.onClick}
              >
                {action.label}
              </Button>
            ))}
            {overflow.length > 0 && (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" size="sm" iconRight="chev-down" data-action-more="">
                    More
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent side="top" align="end">
                  {overflow.map((action) => (
                    <DropdownMenuItem
                      key={action.label}
                      variant={action.danger ? "destructive" : "default"}
                      disabled={action.disabled || action.loading}
                      onSelect={action.onClick}
                    >
                      {action.loading ? `${action.label} (running)` : action.label}
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>
            )}
          </span>
          <Button variant="ghost" size="sm" onClick={onClear}>
            Clear
          </Button>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

.bar {
  position: fixed;
  bottom: var(--v4-space-24);
  left: 50%;
  z-index: 40;
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  max-width: calc(100% - 2 * var(--v4-space-16));
  height: var(--v4-space-48);
  margin-inline: auto;
  padding: 0 var(--v4-space-8) 0 var(--v4-space-16);
  translate: -50% 0;
  border: 1px solid var(--v4-toast-line);
  border-radius: calc(var(--v4-radius-pop) * var(--corners));
  background: var(--v4-toast-bg);
  color: var(--v4-toast-text);
  box-shadow: var(--v4-shadow-pop);
  white-space: nowrap;
}
.bar[data-placement="contained"] {
  position: absolute;
  bottom: var(--v4-space-16);
}
.count {
  display: inline-flex;
  align-items: baseline;
  gap: var(--v4-space-4);
  font-family: var(--v4-type-label-font-family);
  font-size: var(--v4-type-label-font-size);
  line-height: var(--v4-type-label-line-height);
  font-weight: var(--v4-type-label-font-weight);
  letter-spacing: var(--v4-type-label-letter-spacing);
}
.number {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}
.noun {
  color: var(--v4-toast-muted);
}
.selectAll.selectAll {
  color: var(--v4-toast-text);
}
.rule {
  flex: none;
  width: 1px;
  height: var(--v4-space-20);
  background: var(--v4-toast-line);
}
.actions {
  display: flex;
  align-items: center;
  gap: var(--v4-space-4);
  min-width: 0;
  overflow: hidden;
}
@media (max-width: 400px) {
  .selectAll {
    display: none;
  }
  .noun {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
  }
}
